      '(always-latest policy)', () {
    final ref = pinnedRef(sm, 'factory-sm.yml');
    expect(ref, isNotNull, reason: 'uses: line with @main not found');
    expect(
      ref == 'main',
      isTrue,
      reason: 'ref "$ref" is not main — always-latest policy',
    );
  });

