      // mention it in comments; only real YAML would break validation).
      final inheritLine = yaml
          .split('\n')
          .any((l) => l.trimLeft().startsWith('secrets: inherit'));
      expect(
        inheritLine,
        isFalse,
        reason: '${entry.key} must not use secrets: inherit',
      );
    }
  });

