      'ai-teammate (assignee filter on issues, author filter on PRs)', () {
    expect(
      teammate.contains(
        "contains(github.event.issue.assignees.*.login, 'ai-teammate')",
      ),
      isTrue,
      reason: 'issues trigger must key on the ASSIGNEE, not the author',
    );
